public final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Check if the constant pool entry is a CONSTANT_Utf8
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= constantPool.size()) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }
    ConstantPoolEntry entry = constantPool.get(constantPoolEntryIndex);
    if (entry.getTag() != ConstantPoolEntry.CONSTANT_Utf8) {
        throw new IllegalArgumentException("Not a CONSTANT_Utf8 entry: " + entry);
    }

    // Read the string from the class file buffer
    int stringLength = entry.getLength();
    if (stringLength > charBuffer.length) {
        throw new IllegalArgumentException("Char buffer too small for string: " + stringLength);
    }
    classFileBuffer.get(entry.getOffset(), charBuffer, 0, stringLength);

    // Convert the char array to a String
    return new String(charBuffer, 0, stringLength);
}

