public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i + 1 < str.length()) {
                char nextChar = str.charAt(i + 1);
                if (nextChar == 'n') {
                    sb.append('\n');
                    i++;
                } else if (nextChar == 'r') {
                    sb.append('\r');
                    i++;
                } else if (nextChar == 't') {
                    sb.append('\t');
                    i++;
                } else if (nextChar == 'b') {
                    sb.append('\b');
                    i++;
                } else if (nextChar == 'f') {
                    sb.append('\f');
                    i++;
                } else if (nextChar == '\\') {
                    sb.append('\\');
                    i++;
                } else if (nextChar == '\'') {
                    sb.append('\'');
                    i++;
                } else if (nextChar == '\"') {
                    sb.append('\"');
                    i++;
                } else if (nextChar == '0') {
                    sb.append('\0');
                    i++;
                } else if (nextChar == 'u') {
                    if (i + 5 < str.length()) {
                        String hex = str.substring(i + 2, i + 6);
                        sb.append((char) Integer.parseInt(hex, 16));
                        i += 5;
                    } else {
                        throw new Exception("Invalid Unicode escape sequence: " + str.substring(i));
                    }
                } else {
                    throw new Exception("Invalid escape sequence: " + str.substring(i));
                }
            } else {
                throw new Exception("Invalid escape sequence: " + str.substring(i));
            }
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
