        throw new IllegalArgumentException("Invalid nameStart: " + nameStart);
    }
    int nameEnd = buf.length();
    for (int i = nameStart; i < nameEnd; i++) {
        char c = buf.charAt(i);
        if (c == '.' || c == '/') {
            nameEnd = i;
            break;
