public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("Day step must be positive");
    }
    if (timeBucket < 0) {
        throw new IllegalArgumentException("Time bucket must be non-negative");
    }
    long days = timeBucket / 1000000;
    long remainder = timeBucket % 1000000;
    long step = days / dayStep;
    long newDays = step * dayStep;
    long newRemainder = remainder;
    if (newRemainder >= 1000000) {
        newDays += 1;
        newRemainder -= 1000000;
    }
    return newDays * 1000000 + newRemainder;
}

