public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("str cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("session cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("lb cannot be null");
    }
    int length = str.length();
    if (length == 0) {
        return lb;
    }
    int offset = 0;
    while (offset < length) {
        int codePoint = str.codePointAt(offset);
        if (codePoint < 0x80) {
            lb.writeByte((byte) codePoint);
        } else if (codePoint < 0x800) {
            lb.writeByte((byte) (0xC0 | (codePoint >> 6)));
            lb.writeByte((byte) (0x80 | (codePoint & 0x3F)));
        } else if (codePoint < 0x10000) {
            lb.writeByte((byte) (0xE0 | (codePoint >> 12)));
            lb.writeByte((byte) (0x80 | ((codePoint >> 6) & 0x3F)));
            lb.writeByte((byte) (0x80 | (codePoint & 0x3F)));
        } else {
            lb.writeByte((byte) (0xF0 | (codePoint >> 18)));
            lb.writeByte((byte) (0x80 | ((codePoint >> 12) & 0x3F)));
            lb.writeByte((byte) (0x80 | ((codePoint >> 6) & 0x3F)));
            lb.writeByte((byte) (0x80 | (codePoint & 0x3F)));
        }
        offset += Character.charCount(codePoint);
    }
    return lb;
}

