public final byte[] toByteArray() {
    // Calculate the total size of the buffer(s)
    int totalSize = 0;
    for (ByteBuffer buffer : buffers) {
        totalSize += buffer.remaining();
    }

    // Allocate a new byte array to hold the contents of the buffer(s)
    byte[] result = new byte[totalSize];

    // Copy the contents of each buffer into the result array
    int offset = 0;
    for (ByteBuffer buffer : buffers) {
        int length = buffer.remaining();
        buffer.get(result, offset, length);
        offset += length;
    }

    return result;
}

